<?php $labels=array('pengumuman'=>'Pengumuman','agenda'=>'Agenda & Acara','galeri'=>'Galeri Kegiatan');$title=$labels[$type].' | '.($settings['site_name']??'Sukamulya');$this->load->view('site/header',compact('title','settings','menu')); ?>
